 practice(page,'degree-5-find');page.set_viewport_size({'width':375,'height':812});page.locator('.pilot-position-buttons summary').click();page.wait_for_timeout(80);assert page.locator('.pilot-position-buttons summary').inner_text()=='Masquer les boutons de réponse';q=snap(page)['session']['queue'][0];page.locator(f'[data-pilot-action="position"][data-string="{q["target"]["string"]}"][data-fret="{q["target"]["fret"]}"]').click();page.wait_for_timeout(80);assert page.locator('.pilot-position-buttons details').get_attribute('open') is not None;page.screenshot(path=str(OUT/'buttons-v015.png'));page.locator('.pilot-position-buttons summary').click();page.wait_for_timeout(60);assert not page.locator('.pilot-position-buttons details[open]').count()
 # Every open-string timbre preview follows all strings, and system appearance responds live.
