 page.locator('[data-action="stats"]:visible').first.click();page.wait_for_timeout(220);assert page.locator('.progress-cell').count()==30;assert page.locator('.progress-string-label').first.inner_text()=='1 E';page.screenshot(path=str(OUT/'progress-v015.png'),full_page=True)
 # Accidental tuning names get their own ring; ordinary exercises keep seven options.
