 practice(page,'tuning','guitar6','C#2 D#2 F#2 G#2 A#2 C#3');assert page.locator('.pilot-wheel button').count()==12;page.screenshot(path=str(OUT/'dual-wheel-complete-v015.png'))
 # Discovery is not preceded by a launch. A wrong guess never paints the hidden target green.
 seed(page,'guitar6','degree-5');page.locator('.lesson-row[data-module="degree-5"]').click();assert page.locator('.new-exercise-label').count();assert not page.locator('.pilot-count').count();assert not page.locator('.lesson-neck .neck-point').count();page.locator('[data-lesson-string="0"][data-lesson-fret="0"]').dispatch_event('pointerdown',{'button':0});assert not page.locator('.lesson-neck .neck-point[fill="#267342"]').count();assert page.locator('.discovery-direction').inner_text();page.locator('[data-lesson-string="1"][data-lesson-fret="2"]').dispatch_event('pointerdown',{'button':0});assert page.locator('.lesson-neck .neck-point[fill="#267342"]').count()==1;page.screenshot(path=str(OUT/'lesson-v015.png'));page.locator('[data-pilot-action="help-next"]').click();assert not page.locator('.pilot-count').count()
 # Transition duration and direction, including pause, are tested in a real animation context.
 c2=b.new_context(viewport={'width':375,'height':812});q=c2.new_page();q.on('pageerror',lambda e:errors.append(str(e)));practice(q,'opens');q.locator('[data-pilot-action="exit"]').click();q.locator('[data-pilot-action="home"]:visible').click();enable_fast_clock(q);q.locator('.lesson-row[data-module="opens"]').click();assert q.locator('.launch-message').count();values=q.locator('.launch-message').evaluate('''e=>{const a=e.getAnimations().find(a=>a.animationName==='launch-zoom');a.pause();return {duration:a.effect.getTiming().duration,scales:[0,500,1000].map(t=>{a.currentTime=t;return new DOMMatrix(getComputedStyle(e).transform).a})}}''');assert values['duration']==1000;assert values['scales'][0]>values['scales'][1]>values['scales'][2];tick(q,500);q.locator('[data-pilot-action="pause"]').click();tick(q,2000);assert q.locator('.pilot-count').count();q.locator('.pause-card [data-pilot-action="resume-pause"]').click();tick(q,550);assert not q.locator('.pilot-count').count();tick(q,100);first=snap(q)['session']['queue'][0];q.locator(f'[data-note="{first["target"]["midi"]%12}"]').dispatch_event('click');assert 100<=snap(q)['session']['events'][0]['ms']<=300
 assert not errors,errors;print(json.dumps({'answers_100ms_including_errors':True,'parallel_corrections':True,'hint_one_question_only':True,'wheel_fits_five_sizes':True,'persistent_buttons':True,'tuning_voice_preview':True,'system_theme_live':True,'all_30_chromatic_positions':True,'conditional_second_ring':True,'unlimited_lesson_without_revealed_target':True,'one_second_zoom_out':True,'countdown_and_pause_not_timed':True,'errors':errors}));b.close()
